sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float strength;
uniform float angle;
uniform float phase;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float period = size.x / max(amount, 0.5);
    float a = radians(angle);
    float u = dot(coord - size * 0.5, float2(-sin(a), cos(a))) / period + phase;
    float s = clamp(strength, 0.001, 0.999);
    float ink = pow(clamp(1.0 - luma(float3(src.rgb) / float(src.a)), 0.0, 1.0), (1.0 - s) / s);
    float e = abs(fract(u) - 0.5) * period;
    float line = clamp(ink * period * 0.5 - e + 0.5, 0.0, 1.0);
    float3 rgb = mix(float3(color2.rgb), float3(color1.rgb), line);
    return half4(half3(rgb) * src.a, src.a);
}
